def skill():
    ac = 3 + 1
    p = Rational(12) / (Rational(ac, 2))
    return (3 + 1) * p

def _sol():
    p, y = symbols('p y', positive=True)
    A = (p, y)
    C = (p, -1)
    area = Abs(A[0]*C[1] - A[1]*C[0]) / 2
    return p, y, solve([Eq(y, 3*1), Eq(area, 12)], [p, y], dict=True)

def standard():
    p, y, sols = _sol()
    s = sols[0]
    return (s[y] + 1) * s[p]

def unique():
    p, y, sols = _sol()
    return sorted(set((s[y] + 1) * s[p] for s in sols))
